import json, sys
data = json.load(sys.stdin)
registry = json.loads(data['result'])
exps = registry['data']['experiments']

# Show all non-DONE experiments + recent DONE 8k_v2 + gsm8k_qw_rand
for eid, e in exps.items():
    status = e.get('status','')
    if status in ('RUNNING','ANALYZING','PREPARING','PENDING','QUEUED','ALLOCATED'):
        print(f'{eid}: status={status}, conclusion={e.get(\"conclusion\",\"\")}, metrics={json.dumps(e.get(\"metrics\",{}))}')

print('--- DONE 8k_v2 ---')
for eid, e in exps.items():
    if e.get('status') == 'DONE' and '8k_v2' in eid:
        print(f'{eid}: conclusion={e.get(\"conclusion\",\"\")}, metrics={json.dumps(e.get(\"metrics\",{}))}')

print('--- gsm8k_qw_rand ---')
for eid, e in exps.items():
    if 'gsm8k_qw_rand' in eid:
        print(f'{eid}: status={e.get(\"status\",\"\")}, conclusion={e.get(\"conclusion\",\"\")}, metrics={json.dumps(e.get(\"metrics\",{}))}')

print('--- DS accuracy (non-8k) ---')
for eid, e in exps.items():
    if eid.startswith('acc_ds_') and '8k' not in eid:
        print(f'{eid}: status={e.get(\"status\",\"\")}, conclusion={e.get(\"conclusion\",\"\")}, metrics={json.dumps(e.get(\"metrics\",{}))}')

print('--- QW accuracy ---')
for eid, e in exps.items():
    if eid.startswith('acc_qw_'):
        print(f'{eid}: status={e.get(\"status\",\"\")}, conclusion={e.get(\"conclusion\",\"\")}, metrics={json.dumps(e.get(\"metrics\",{}))}')
"

